<?php

declare(strict_types=1);

namespace Tests\Generated\MyCrud\FilmText;

use CodeIgniter\Test\CIUnitTestCase;

/**
 * Structural smoke test generated by myCrudCI4.
 *
 * Verifies that the components required by the architecture are published and
 * loadable through the autoloader. It does not access application data.
 */
final class FilmTextStructureTest extends CIUnitTestCase
{
    private const EXPECTED_CLASSES = array (
  0 => 'App\\Models\\FilmTextModel',
  1 => 'App\\Controllers\\FilmTextController',
  2 => 'App\\Validation\\FilmTextRules',
  3 => 'App\\Entities\\FilmTextEntity',
  4 => 'App\\Services\\FilmTextService',
  5 => 'App\\Controllers\\Api\\V1\\FilmTextApiController',
  6 => 'App\\API\\Resources\\FilmTextResource',
  7 => 'App\\Validation\\FilmTextApiRules',
);

    public function testGeneratedClassesAreAutoloadable(): void
    {
        foreach (self::EXPECTED_CLASSES as $class) {
            $this->assertTrue(
                class_exists($class),
                'Generated class is not autoloadable: ' . $class
            );
        }
    }
}
